import os,subprocess
from playwright.sync_api import sync_playwright,expect
server=subprocess.Popen(['node','scripts/serve.mjs'],env={**os.environ,'PORT':'14347'},stdout=subprocess.DEVNULL)
try:
 with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=b.new_page(viewport={'width':1280,'height':900});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:14347');page.evaluate('''async()=>{const{createProject}=await import('/project.js');localStorage.setItem('playform.projects',JSON.stringify([{...createProject('Car QA','blank3d'),objects:createProject('Car QA','blank3d').objects.filter(o=>['character','ground'].includes(o.mesh))}]))}''');page.reload();page.locator('.project-open').click();page.locator('button[data-stage="Add"]').click();page.locator('.simple-sidebar [data-add="car"]').click();saved=page.evaluate('JSON.parse(localStorage.getItem("playform.projects"))[0]');assert any(o['mesh']=='character' for o in saved['objects']);assert next(o for o in saved['objects']if o['id']==saved['controlledObjectId'])['mesh']=='car';page.locator('button[data-stage="Events"]').click();page.locator('#add-input-event').click();page.locator('[data-rule="0"][data-field="action"]').select_option('addvariable');page.locator('[data-rule="0"][data-field="variable"]').select_option('Score');page.locator('button[data-stage="Scene"]').click();page.locator('#navigation-play').click();page.wait_for_timeout(350);z=float(page.locator('.studio3d').get_attribute('data-z'));page.keyboard.down('KeyW');page.wait_for_timeout(800);page.keyboard.down('KeyD');page.wait_for_timeout(400);page.keyboard.up('KeyD');page.keyboard.up('KeyW');assert float(page.locator('.studio3d').get_attribute('data-z'))<z-1;page.keyboard.press('KeyE');page.wait_for_timeout(200);expect(page.locator('.three-runtime')).to_contain_text('Coins 1');page.screenshot(path='screenshots/arcade-car-tested.png');assert not errors,errors;b.close();print('PASS car preset preserves character, drives/steers and runs a configurable key event',flush=True)
finally:server.terminate();server.wait()
